def generate_palindrome(length):
    if length < 1:
        return "Length must be greater than 0"
    elif length == 1:
        return "a"
    else:
        half_length = (length + 1) // 2
        half_string = ''.join(chr(97 + i % 26) for i in range(half_length))
        palindrome = half_string + half_string[::-1]
        if length % 2 == 0:
            return palindrome
        else:
            middle_char = chr(97 + (half_length - 1) % 26)
            return palindrome[:length//2] + middle_char + palindrome[length//2:][::-1]

print(generate_palindrome(255))
```

